import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Store listing & release metadata","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/store-listing.md"},"headers":[],"relativePath":"apps/mobile/store-listing.md","filePath":"apps/mobile/store-listing.md"}'),s={name:"apps/mobile/store-listing.md"};function n(r,e,l,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="store-listing-release-metadata" tabindex="-1">Store listing &amp; release metadata <a class="header-anchor" href="#store-listing-release-metadata" aria-label="Permalink to &quot;Store listing &amp; release metadata&quot;">​</a></h1><p>Text/copy deliverables for task 20.4 (<a href="./epics/release.html">docs/epics/release.md</a>), drafted so they&#39;re ready to paste into App Store Connect and Play Console. Icons and splash screens (also part of 20.4) are handled separately — see <a href="./../resources.html">resources/</a> and <code>scripts/generate-app-assets.mjs</code>.</p><p><strong>Scope note</strong>: everything in this doc is text an agent can draft from the existing codebase and docs. It does <strong>not</strong> cover feature graphic design or screenshots (blocked on product/design decisions — see ROADMAP), or the account-dependent steps called out in <a href="#still-blocked-human-handoff">Still blocked</a> below (Apple Developer Program / Google Play Console enrollment, actual submission).</p><h2 id="_1-listing-copy" tabindex="-1">1. Listing copy <a class="header-anchor" href="#_1-listing-copy" aria-label="Permalink to &quot;1. Listing copy&quot;">​</a></h2><p>Grounded in <a href="./../CONCEPT.html">CONCEPT.md</a>&#39;s framing and the existing PWA manifest copy (<code>sovereign/runtime/public/manifest.json</code>), so the mobile listing doesn&#39;t invent a different voice from what&#39;s already shipped.</p><h3 id="app-name" tabindex="-1">App name <a class="header-anchor" href="#app-name" aria-label="Permalink to &quot;App name&quot;">​</a></h3><p><strong>Sovereign</strong> (matches <code>CFBundleDisplayName</code> / PWA <code>short_name</code>). Flagging, not deciding: this is a short, generic word — worth a trademark/App Store search-collision check before submission, since that&#39;s not something I can verify from inside this repo.</p><h3 id="subtitle-ios-≤30-chars-short-description-play-≤80-chars" tabindex="-1">Subtitle (iOS, ≤30 chars) / short description (Play, ≤80 chars) <a class="header-anchor" href="#subtitle-ios-≤30-chars-short-description-play-≤80-chars" aria-label="Permalink to &quot;Subtitle (iOS, ≤30 chars) / short description (Play, ≤80 chars)&quot;">​</a></h3><blockquote><p>Your self-hosted workspace.</p></blockquote><p>27 characters — fits both fields as-is, and is a direct reuse of the PWA manifest&#39;s <code>description</code> field.</p><h3 id="full-description-≤4000-chars-both-stores" tabindex="-1">Full description (≤4000 chars both stores) <a class="header-anchor" href="#full-description-≤4000-chars-both-stores" aria-label="Permalink to &quot;Full description (≤4000 chars both stores)&quot;">​</a></h3><blockquote><p>Sovereign is a self-hosted workspace — you run it on your own server, you own your data, and no company sits in the middle. This app is the native Sovereign client: enter the address of your own Sovereign instance, and the app connects directly to it. There&#39;s no separate account with us, because there is no &quot;us&quot; in the middle — your instance is the whole product.</p><p>This app doesn&#39;t come with a fixed backend or a bundled workspace. You (or whoever runs your Sovereign instance) control what plugins, data, and features are available. The app itself is a thin, native shell: it handles connecting to your instance, remembering it between launches, and letting you add and switch between multiple instances if you use more than one.</p><p>Requires an existing self-hosted Sovereign instance to connect to. Sovereign is open source — see <a href="https://github.com/sovereignfs/sovereign" target="_blank" rel="noreferrer">https://github.com/sovereignfs/sovereign</a> to set one up.</p><p>This app does not collect analytics or telemetry, and does not send your data anywhere except the instance URL you provide.</p></blockquote><p>~1000 characters — well under budget on both stores if more detail (plugin ecosystem, specific features) gets added later.</p><h3 id="keywords-ios-≤100-chars-comma-separated-no-spaces-after-commas" tabindex="-1">Keywords (iOS, ≤100 chars, comma-separated, no spaces after commas) <a class="header-anchor" href="#keywords-ios-≤100-chars-comma-separated-no-spaces-after-commas" aria-label="Permalink to &quot;Keywords (iOS, ≤100 chars, comma-separated, no spaces after commas)&quot;">​</a></h3><blockquote><p>self-hosted,workspace,productivity,privacy,open source,sovereign,personal server</p></blockquote><p>97 characters.</p><h3 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to &quot;Category&quot;">​</a></h3><p>Productivity (matches the PWA manifest&#39;s <code>categories: [&quot;productivity&quot;]</code>).</p><h3 id="support-marketing-urls" tabindex="-1">Support / marketing URLs <a class="header-anchor" href="#support-marketing-urls" aria-label="Permalink to &quot;Support / marketing URLs&quot;">​</a></h3><p>Both stores require a support URL; App Store Connect also wants a marketing URL and Play Console a privacy policy URL. Not drafted here — these need to point at real, live pages (a support contact/issue tracker, and a privacy policy — see <a href="#2-privacy-labels--data-safety-declarations">§2</a> for what that policy needs to say), which is a hosting/ownership decision outside this repo&#39;s scope.</p><h2 id="_2-privacy-labels-data-safety-declarations" tabindex="-1">2. Privacy labels / data safety declarations <a class="header-anchor" href="#_2-privacy-labels-data-safety-declarations" aria-label="Permalink to &quot;2. Privacy labels / data safety declarations&quot;">​</a></h2><p>Grounded in what the shell actually does, verified against the code, not assumed:</p><ul><li><strong>No telemetry or analytics by default</strong> — explicit position in <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0058-native-mobile-app-shell.md" target="_blank" rel="noreferrer">sovereign RFC 0058</a>: &quot;The shell should not introduce telemetry by default. Any future crash reporting or analytics must follow Sovereign&#39;s privacy-first posture and be opt-in or operator-controlled.&quot; Nothing in this codebase contradicts that — no analytics SDK, no crash reporter, is integrated.</li><li><strong>Three native capabilities exist today</strong> (<a href="./../android/app/src/main/java/fs/sovereign/mobile/BridgeCapabilities.java.html">BridgeCapabilities.java</a>, <a href="./../ios/App/App/Bridge.swift.html">Bridge.swift</a>): <code>haptics.impact</code> (no data, no permission), <code>notifications.native</code> (local notifications only — not push/remote; requires the OS notification permission, requested inline at point of use), and <code>camera.photo</code> (task 20.6 — picks a photo from the library or captures one from the camera, returned to the calling plugin as a base64 data URL; the library source needs no permission at all (system photo picker), the camera source requires the OS camera permission, requested inline at point of use). No location, contacts, microphone, or any other sensitive capability is implemented. Every <code>camera.photo</code> call is entirely user-initiated (a plugin button, not something the app does on its own) and the resulting image never leaves the device except to whichever instance origin the calling plugin itself sends it to — the shell has no camera-photo-specific network destination.</li><li><strong>What the app stores locally</strong>: the list of instance URLs the user has added (<code>@capacitor/preferences</code>, on-device only) and the session cookie for whichever instance is currently loaded (browser/WebView cookie jar, per-origin — see <a href="./adrs/0003-cookie-in-webview-auth.html">ADR 0003</a>). Neither leaves the device except to the instance origin the user themselves entered.</li><li><strong>Network access</strong>: the app talks to exactly one destination — the instance origin the user enters — for validation (<code>GET /api/instance</code>) and then for all WebView content thereafter. No other network destination is contacted by shell code.</li></ul><h3 id="apple-app-privacy-nutrition-label-—-app-store-connect" tabindex="-1">Apple App Privacy (&quot;nutrition label&quot;) — App Store Connect <a class="header-anchor" href="#apple-app-privacy-nutrition-label-—-app-store-connect" aria-label="Permalink to &quot;Apple App Privacy (&quot;nutrition label&quot;) — App Store Connect&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Data collected by this app</td><td><strong>None</strong> (the app itself collects nothing; any data handling happens on the user&#39;s own instance, outside Apple&#39;s App Privacy scope, exactly like Safari isn&#39;t asked to declare what websites do)</td></tr><tr><td>Data linked to the user</td><td>N/A</td></tr><tr><td>Data used to track the user</td><td>No</td></tr></tbody></table><h3 id="google-play-data-safety-form" tabindex="-1">Google Play Data Safety form <a class="header-anchor" href="#google-play-data-safety-form" aria-label="Permalink to &quot;Google Play Data Safety form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Answer</th></tr></thead><tbody><tr><td>Does your app collect or share any of the required user data types?</td><td><strong>No</strong></td></tr><tr><td>Is all user data encrypted in transit?</td><td>Yes — the app enforces <code>https://</code> (or explicit <code>http://</code> only if the user types it, e.g. a LAN dev instance — see <a href="../src/validate.ts"><code>normalizeInstanceUrl</code></a>)</td></tr><tr><td>Does your app allow users to request data deletion?</td><td>Not applicable from the app itself — deletion is a function of the user&#39;s own instance, not this shell</td></tr></tbody></table><h3 id="privacy-policy-page-required-by-both-stores" tabindex="-1">Privacy policy page (required by both stores) <a class="header-anchor" href="#privacy-policy-page-required-by-both-stores" aria-label="Permalink to &quot;Privacy policy page (required by both stores)&quot;">​</a></h3><p>Needs a real, hosted page — drafting the <em>content</em> here since that&#39;s groundable, even though hosting it isn&#39;t this repo&#39;s job:</p><blockquote><p>This app does not collect, store, or transmit any personal data to [org/maintainer name]. It connects only to the self-hosted Sovereign instance URL you provide, which you or your organization control. Any data handling that occurs happens on that instance, under its own privacy policy — not this app&#39;s. Locally, the app stores only the list of instance URLs you&#39;ve added and your session cookie for the currently-connected instance, both on-device only.</p></blockquote><h2 id="_3-minimum-supported-os-versions" tabindex="-1">3. Minimum supported OS versions <a class="header-anchor" href="#_3-minimum-supported-os-versions" aria-label="Permalink to &quot;3. Minimum supported OS versions&quot;">​</a></h2><p><a href="https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0058-native-mobile-app-shell.md" target="_blank" rel="noreferrer">Sovereign RFC 0058</a> leaves this as an explicit open question (&quot;Minimum supported iOS and Android versions&quot;) with no stated rationale either way — this is a genuine decision for you to confirm, not something I should silently pick.</p><p><strong>What&#39;s already configured</strong> (Capacitor/Ionic scaffold defaults, not a deliberate product decision until now):</p><ul><li>iOS: <code>IPHONEOS_DEPLOYMENT_TARGET = 15.0</code></li><li>Android: <code>minSdkVersion = 24</code> (Android 7.0, <code>targetSdkVersion = 36</code>)</li></ul><p><strong>My recommendation: keep both as-is.</strong> Reasoning:</p><ul><li>Nothing in this codebase depends on an iOS or Android API newer than what these floors already provide — the bridge transport&#39;s <code>WebViewFeature.isFeatureSupported()</code> checks (<a href="./../android/app/src/main/java/fs/sovereign/mobile/NavigationPolicyWebViewClient.java.html">NavigationPolicyWebViewClient.java</a>) already degrade gracefully on older WebView builds rather than requiring a version floor.</li><li>These floors have already been built and tested this cycle, including end-to-end verification on a real physical iPhone (2026-08-06) and Android Emulator — raising either floor now would be undoing tested configuration for no stated reason, and lowering either would be untested.</li><li>iOS 15+ and Android 7+ are both old enough to cover the large majority of actively-used devices per each platform&#39;s own public distribution data — I&#39;m not citing a specific percentage since I can&#39;t verify current figures from inside this repo, but neither floor is aggressively new.</li></ul><p>If you want a different floor, it&#39;s a one-line change in each project (<code>IPHONEOS_DEPLOYMENT_TARGET</code> / <code>variables.gradle</code>&#39;s <code>minSdkVersion</code>), not a structural one.</p><h2 id="_4-store-review-checklist" tabindex="-1">4. Store-review checklist <a class="header-anchor" href="#_4-store-review-checklist" aria-label="Permalink to &quot;4. Store-review checklist&quot;">​</a></h2><p>For whoever submits, and to pre-empt reviewer questions about an app that&#39;s &quot;just a URL box&quot; on first launch:</p><ul><li>[ ] <strong>Reviewer notes / demo instance</strong>: both stores let you attach notes for the human reviewer. Since this app requires a real Sovereign instance to do anything, <strong>provide a working demo instance URL and test credentials in the reviewer notes</strong> — without one, a reviewer with no self-hosted Sovereign instance cannot get past onboarding and may reject for &quot;incomplete functionality.&quot;</li><li>[ ] <strong>Permissions requested, and why</strong> (for both stores&#39; permission justification fields): <ul><li><code>android.permission.INTERNET</code> — required for all WebView content; Android does not surface this to users as a runtime prompt.</li><li><code>android.permission.VIBRATE</code> — backs <code>haptics.impact</code>; not user-facing as a permission prompt either.</li><li><code>android.permission.POST_NOTIFICATIONS</code> (Android 13+) / iOS notification permission — backs <code>notifications.native</code> (local notifications only, not push). Requested inline, not at launch — see <a href="./../android/app/src/main/java/fs/sovereign/mobile/BridgeCapabilities.java.html">BridgeCapabilities.java</a>.</li><li><code>android.permission.CAMERA</code> / iOS <code>NSCameraUsageDescription</code> — backs <code>camera.photo</code>&#39;s <code>&quot;camera&quot;</code> source only. Requested inline, at the point a plugin calls <code>sdk.device.camera.photo(&#39;camera&#39;, ...)</code> — never at launch. The <code>&quot;library&quot;</code> source needs no permission on either platform (Android&#39;s system photo picker, iOS&#39;s <code>PHPickerViewController</code>, both run out-of-process and hand back a scoped reference to just the photo the user picked).</li><li>No location, contacts, microphone, or other sensitive permission is requested by anything in this repo.</li></ul></li><li>[ ] <strong>External links leave the app</strong>: same-origin content (the connected instance) stays in-app; cross-origin links open in the system browser — see <a href="./adrs/0007-navigation-policy-enforcement.html">ADR 0007</a>. Reviewers sometimes flag apps that trap all navigation in-app; this one explicitly doesn&#39;t.</li><li>[ ] <strong>No login/account system of our own</strong>: there&#39;s nothing to explain about account creation, deletion, or data export from <em>this app</em> — auth happens entirely on the user&#39;s own instance. Store review guidelines that require an in-app account-deletion path (Apple guideline 5.1.1(v)) don&#39;t apply the normal way; be ready to explain this if flagged, pointing at the demo instance&#39;s own account settings.</li><li>[ ] <strong>Apple guideline 4.2 (minimum functionality)</strong> risk: flagged previously in <a href="./epics/shell.html">docs/epics/shell.md</a>&#39;s Risks section — a WebView wrapper needs the self-hosted-client precedent (Nextcloud, Bitwarden, Element) to be persuasive; the reviewer notes/demo instance above are the main mitigation.</li><li>[ ] <strong>Offline behavior</strong>: not yet fully scoped (see <a href="./research/0003-webview-offline-behavior.html">research 0003</a>) — confirm what happens with no network before submission, since an unhandled blank screen on connection loss is a common rejection reason.</li></ul><h2 id="still-blocked-human-handoff" tabindex="-1">Still blocked (human handoff) <a class="header-anchor" href="#still-blocked-human-handoff" aria-label="Permalink to &quot;Still blocked (human handoff)&quot;">​</a></h2><p>Not something an agent should attempt — these need real accounts, payment, and identity verification:</p><ul><li><strong>Apple Developer Program enrollment</strong> ($99/year) — required before an App Store Connect app record can even be created.</li><li><strong>Google Play Console developer account</strong> ($25 one-time) — same, for Play Console.</li><li><strong>Production signing</strong>: this session&#39;s iOS verification used automatic <em>development</em> signing (<code>Apple Development: ...</code>) for a real-device test build — a <strong>distribution</strong> certificate + provisioning profile (or App Store Connect API key for CI) is a separate, later step once the developer account exists.</li><li><strong>Actual submission and review</strong> — TestFlight internal testing / Play internal testing track, then public release, both require the app record and signing above to exist first.</li></ul>',43)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
